// stores/cart.js
import { defineStore } from "pinia";

export const useCartStore = defineStore("cart", {
    state: () => ({ items: [], coupon: null }),
    getters: {
        subtotal: (state) => state.items.reduce((s, i) => s + i.price * i.qty, 0),
        total() {
            const off = this.coupon === "FLAT50" && this.subtotal >= 500 ? 50 : 0;
            return this.subtotal - off;
        }
    },
    actions: {
        add(product, qty = 1) {
            const line = this.items.find(i => i.id === product.id);
            if (line) line.qty += qty;
            else this.items.push({ ...product, qty });
        },
        applyCoupon(code) {
            this.coupon = code;
        }
    }
});

