# tasks.py
from celery import Celery

celery = Celery("app", broker="redis://localhost:6379/0",
                backend="redis://localhost:6379/1")

@celery.task(bind=True)
def build_report(self, user_id, month):
    try:
        rows = fetch_orders(user_id, month)          # slow DB query
        path = write_csv(rows, f"report-{user_id}-{month}.csv")
        return {"path": path, "rows": len(rows)}
    except ConnectionError as exc:
        raise self.retry(exc=exc, countdown=3 * 2 ** self.request.retries, max_retries=5)

# app.py (Flask)
@app.post("/api/reports")
def start_report():
    job = build_report.delay(current_user.id, request.json["month"])
    return {"job_id": job.id}, 202

@app.get("/api/jobs/<job_id>")
def job_status(job_id):
    res = build_report.AsyncResult(job_id)
    return {"state": res.state, "result": res.result if res.successful() else None}

